<map version="1.0.1"><node CREATED="1747229376987" ID="ID_root" MODIFIED="1747229376987" TEXT="文件流复习"><node CREATED="1747229376987" ID="ID_bde465a3ea7911fe" POSITION="right" MODIFIED="1747229376987" TEXT="流"><node CREATED="1747229376987" ID="ID_30658e59948eea34" MODIFIED="1747229376987" TEXT="流就是一个编程模型。就是用来给程序读取或者输出数据到外部的。&amp;nbsp;&amp;lt;br&amp;gt;让程序员，可以用一种比较简单的方式读取数据。"><node CREATED="1747229376987" ID="ID_88091f87245117c8" MODIFIED="1747229376987" TEXT="就是一个固定的套路。只需要遵循这个套路，就可以从文件中读数据。&amp;lt;br&amp;gt;固定的几个步骤。&amp;nbsp;&amp;nbsp;"></node><node CREATED="1747229376987" ID="ID_1e690553109f2998" MODIFIED="1747229376987" TEXT="读数据：&amp;nbsp;简单说就是一个管子连着文件，一个管子连着程序。&amp;lt;br&amp;gt;在程序中，有一个开关，拧一下这个开关，进来一些数据。&amp;nbsp;&amp;lt;br&amp;gt;最后，拧到没数据的时候，数据就读完了。"></node></node><node CREATED="1747229376987" ID="ID_241a6a4ebe2ea05e" MODIFIED="1747229376987" TEXT="文件流：&amp;nbsp;就是操作文件的一个流。我们可以通过文件流，从文件中读数据，往文件里面写数据"></node><node CREATED="1747229376987" ID="ID_b54b8c3b859fab6a" MODIFIED="1747229376987" TEXT="路径问题"><node CREATED="1747229376987" ID="ID_004ebadf99960a85" MODIFIED="1747229376987" TEXT="绝对路径"><node CREATED="1747229376987" ID="ID_c6f9b7ada774f111" MODIFIED="1747229376987" TEXT="windows里面的绝对路径，就是从盘符开始的一个路径&amp;lt;br&amp;gt;E:\Users\zhoubing\Desktop\cpp64_code\Day15_文件流\06_路径问题\test2\test3\111.txt&amp;lt;br&amp;gt;"></node><node CREATED="1747229376987" ID="ID_6f464ab1ceb7ff5d" MODIFIED="1747229376987" TEXT="Linux里面的绝对路径，就是从/&amp;lt;br&amp;gt;/wangdao/share/c++/tools/1.mp4&amp;lt;br&amp;gt;"></node><node CREATED="1747229376987" ID="ID_409e67d2beea030f" MODIFIED="1747229376987" TEXT="绝对路径用的少"><node CREATED="1747229376987" ID="ID_d361968625ddd51a" MODIFIED="1747229376987" TEXT="路径基本不会出错，非常方便，但是在工作中，由于需要多人协作，无法保证绝对路径的使用。&amp;nbsp;"></node></node></node><node CREATED="1747229376987" ID="ID_4803e89f5205ccbc" MODIFIED="1747229376987" TEXT="相对路径"><node CREATED="1747229376987" ID="ID_30041f12863f7c6e" MODIFIED="1747229376987" TEXT="相对的是谁。&amp;nbsp;在vs中，写代码的时候，相对路径指的是：程序启动时候的项目根目录"></node><node CREATED="1747229376987" ID="ID_2de1437cfeb33075" MODIFIED="1747229376987" TEXT="相对路径的关键问题是：&amp;nbsp;相对的是谁"></node></node><node CREATED="1747229376987" ID="ID_f3c9df271a874bbe" MODIFIED="1747229376987" TEXT="相对路径和绝对路径，是用来在程序中唯一定位一个文件的。&amp;nbsp;&amp;lt;br&amp;gt;文件流，里面需要用路径来唯一确定一个文件。&amp;nbsp;"></node><node CREATED="1747229376987" ID="ID_c8c21e45a3586f14" MODIFIED="1747229376987" TEXT=".当前路径。 ..&amp;nbsp;上一级路径"></node></node></node><node CREATED="1747229376987" ID="ID_84d173bb8e7cc9a7" POSITION="right" MODIFIED="1747229376987" TEXT="API"><node CREATED="1747229376987" ID="ID_28c3863661b63401" MODIFIED="1747229376987" TEXT="基础操作"><node CREATED="1747229376987" ID="ID_be87851c9f98b5bd" MODIFIED="1747229376987" TEXT="fopen"><node CREATED="1747229376987" ID="ID_88b77b32ef06c231" MODIFIED="1747229376987" TEXT="打开文件流"></node><node CREATED="1747229376987" ID="ID_bbd9985e68ccf0be" MODIFIED="1747229376987" TEXT="FILE* fopen(const char *path, const char *mode);&amp;lt;br&amp;gt;"><node CREATED="1747229376987" ID="ID_b81114f53dfa3bf8" MODIFIED="1747229376987" TEXT="FILE是一个结构体。&amp;nbsp;里面存储了各种信息。&amp;nbsp;但是我们目前不关心字段，&amp;lt;br&amp;gt;我们只要知道，后续的操作都是以&amp;nbsp;FILE *&amp;nbsp;作为参数的。&amp;nbsp;"></node></node></node><node CREATED="1747229376987" ID="ID_19c6f66e0db2ca87" MODIFIED="1747229376987" TEXT="fclose"><node CREATED="1747229376987" ID="ID_21160bbd90d2f444" MODIFIED="1747229376987" TEXT="关闭文件流"></node></node><node CREATED="1747229376987" ID="ID_393058a188160d36" MODIFIED="1747229376987" TEXT="流操作的固定步骤"><node CREATED="1747229376987" ID="ID_5b5320abf75c57c1" MODIFIED="1747229376987" TEXT="1.打开文件流&amp;lt;br&amp;gt;2.检查拿到的FILE指针，是否为空&amp;lt;br&amp;gt;3.用完之后，&amp;lt;br&amp;gt;4.关闭文件流"><node CREATED="1747229376987" ID="ID_6be831a8f5f4f9e1" MODIFIED="1747229376987" TEXT="fclose(fp);&amp;lt;br&amp;gt;缓冲区的数据，会刷新出去"></node></node></node><node CREATED="1747229376987" ID="ID_1babba077af439a1" MODIFIED="1747229376987" TEXT="fgetc/fputc"><node CREATED="1747229376987" ID="ID_8cd6599d02e28be5" MODIFIED="1747229376987" TEXT="从文件流里读数据。&amp;nbsp;一个字节一个字节的读。&amp;nbsp;读到最后，如果没数据了，这时候返回 -1(EOF)"></node><node CREATED="1747229376987" ID="ID_4195d487b7de869c" MODIFIED="1747229376987" TEXT="fputc :&amp;nbsp;把程序里面的数据，输出到文件中。&amp;nbsp;"><node CREATED="1747229376987" ID="ID_a2eb5a66f84104bd" MODIFIED="1747229376987" TEXT="int fgetc(FILE* stream);"></node><node CREATED="1747229376987" ID="ID_a0873bccbf58c5ec" MODIFIED="1747229376987" TEXT="int fputc(int c, FILE* stream);"></node></node><node CREATED="1747229376987" ID="ID_e67309d35579b0f3" MODIFIED="1747229376987" TEXT="单个字符单个字符处理的。&amp;nbsp;"></node><node CREATED="1747229376987" ID="ID_297d7016ced7f2e1" MODIFIED="1747229376987" TEXT="使用fgetc、fputc完成一个文件的复制工作。&amp;nbsp;"></node></node><node CREATED="1747229376987" ID="ID_8e6522be2b2ad3d5" MODIFIED="1747229376987" TEXT="fgets/fputs"><node CREATED="1747229376987" ID="ID_333195c285ed97dc" MODIFIED="1747229376987" TEXT="一个字符串，一个字符串拿数据"></node></node><node CREATED="1747229376987" ID="ID_68e43caab40e5807" MODIFIED="1747229376987" TEXT="模式的问题"><node CREATED="1747229376987" ID="ID_1cbf1580f09d2340" MODIFIED="1747229376987" TEXT="r表示读"><node CREATED="1747229376987" ID="ID_206af6aff344ebcd" MODIFIED="1747229376987" TEXT="文件不存在会报错。&amp;nbsp;"></node></node><node CREATED="1747229376987" ID="ID_590a3c63a7fcba6d" MODIFIED="1747229376987" TEXT="w表示写"><node CREATED="1747229376987" ID="ID_70f4d4dcd67af929" MODIFIED="1747229376987" TEXT="文件不存在，会新建文件"></node><node CREATED="1747229376987" ID="ID_c76df84821aec817" MODIFIED="1747229376987" TEXT="文件存在，会截断文件"></node></node><node CREATED="1747229376987" ID="ID_cecb4ced40e70159" MODIFIED="1747229376987" TEXT="a表示追加"><node CREATED="1747229376987" ID="ID_6bc28398710ea3a0" MODIFIED="1747229376987" TEXT="在文件后面追加"></node></node><node CREATED="1747229376987" ID="ID_d8c2f80b80ec01cd" MODIFIED="1747229376987" TEXT="平时，我们在使用文件流的时候，一般很少打开一个文件流，既读又写，而且这个场景非常容易出错。&amp;nbsp;&amp;lt;br&amp;gt;所以，建议，使用流，要么使用这个流读，要么使用这个流写。&amp;nbsp;"></node></node><node CREATED="1747229376987" ID="ID_49c4aa14ed54f857" MODIFIED="1747229376987" TEXT="换行符问题"><node CREATED="1747229376987" ID="ID_f63e84e5a750fbc1" MODIFIED="1747229376987" TEXT="在windows中，使用&amp;nbsp; \r\n作为换行符&amp;lt;br&amp;gt;在Linux/Mac中，使用&amp;nbsp; \n作为换行符"></node><node CREATED="1747229376987" ID="ID_312a6f39bd0dd296" MODIFIED="1747229376987" TEXT="在C中，这里有一个适配，在程序中，向文件中输出&amp;nbsp; \n(换行符)，但是最终存储到文件中，是&amp;nbsp; \r\n&amp;lt;br&amp;gt;文件中是&amp;nbsp; \r\n ，程序在读取的时候，会变成 \n"></node></node><node CREATED="1747229376987" ID="ID_ee1c4c0678cd4bd1" MODIFIED="1747229376987" TEXT="fscanf和fprintf&amp;nbsp;"><node CREATED="1747229376987" ID="ID_10e8736f7aaebebd" MODIFIED="1747229376987" TEXT="输入和输出。以一种格式化的方式输入和输出"></node><node CREATED="1747229376987" ID="ID_14db406146693432" MODIFIED="1747229376987" TEXT="fprintf(fp, &amp;quot;%d %lf&amp;quot;, num1, f1)"></node></node><node CREATED="1747229376987" ID="ID_c62f27a74ca68885" MODIFIED="1747229376987" TEXT="fread和fwrite"><node CREATED="1747229376987" ID="ID_dcc6d5cc2dab4639" MODIFIED="1747229376987" TEXT="以二进制的方式读取或者输入"></node><node CREATED="1747229376987" ID="ID_5f1145c8f7e049de" MODIFIED="1747229376987" TEXT="好处：&amp;nbsp;更快一点"></node></node><node CREATED="1747229376987" ID="ID_ad0017ca1e20b659" MODIFIED="1747229376987" TEXT="不要死记硬背函数。&amp;nbsp;主要先理解这些函数是干什么的。&amp;nbsp;"><node CREATED="1747229376987" ID="ID_70d66760c1d3a338" MODIFIED="1747229376987" TEXT="后续在碰到这些功能的时候，心中知道要用哪个函数&amp;lt;br&amp;gt;再去查入参和返回值，再使用"></node></node></node><node CREATED="1747229376987" ID="ID_c7a0cc237343e44a" MODIFIED="1747229376987" TEXT="API非常多。&amp;nbsp;建议大家按照种类记。建议只记功能。&amp;nbsp;"><node CREATED="1747229376987" ID="ID_c492f8ff67e60d7b" MODIFIED="1747229376987" TEXT="perror(&amp;quot;hello&amp;quot;)"></node></node><node CREATED="1747229376987" ID="ID_922ab37e9c36e474" MODIFIED="1747229376987" TEXT="API"><node CREATED="1747229376987" ID="ID_9261f8453ab87361" MODIFIED="1747229376987" TEXT="就是一些函数，系统提供的，完成特定功能的。&amp;nbsp;"></node></node></node></node></map>